WITH ranked AS ( SELECT f.id::text AS file_id, f.path, f.size_bytes AS size, EXTRACT(EPOCH FROM f.updated_at) AS mtime, c.chunk_index, LEFT(c.content, 4000) AS search_snippet, (1 - (c.embedding <=> CAST(#{vector, jdbcType=LONGVARCHAR} AS vector)))::double precision AS search_score, ROW_NUMBER() OVER ( PARTITION BY f.id ORDER BY c.embedding <=> CAST(#{vector, jdbcType=LONGVARCHAR} AS vector), c.chunk_index ASC ) AS file_rank FROM document_chunks c JOIN documents d ON d.id = c.document_id JOIN files f ON f.id = d.file_id WHERE f.user_id = CAST(#{userId, jdbcType=VARCHAR} AS uuid) AND f.is_dir = false AND d.source_revision = f.revision AND c.source_revision = d.source_revision AND c.embedding IS NOT NULL AND c.embedding_fingerprint = #{fingerprint, jdbcType=VARCHAR}
AND (f.path = #{prefix, jdbcType=VARCHAR} OR f.path LIKE CONCAT(#{prefix, jdbcType=VARCHAR}, '/%'))
) SELECT file_id, path, size, mtime, chunk_index, search_snippet, search_score FROM ranked WHERE file_rank = 1 ORDER BY search_score DESC, lower(path) ASC LIMIT #{limit}

SELECT c.id::text AS id, c.content, c.source_revision, c.chunk_version, d.id::text AS document_id, f.path FROM document_chunks c JOIN documents d ON d.id = c.document_id JOIN files f ON f.id = d.file_id WHERE f.user_id = CAST(#{userId, jdbcType=VARCHAR} AS uuid) AND d.source_revision = f.revision AND c.source_revision = d.source_revision
AND f.path IN
#{path, jdbcType=VARCHAR}
AND (#{fingerprint, jdbcType=VARCHAR} IS NULL OR c.embedding_fingerprint IS DISTINCT FROM #{fingerprint, jdbcType=VARCHAR}) ORDER BY c.id ASC LIMIT #{limit}

