UPDATE document_chunks c SET embedding = NULL, embedding_fingerprint = NULL FROM documents d JOIN files f ON f.id = d.file_id WHERE c.document_id = d.id AND d.source_revision = f.revision AND c.source_revision = d.source_revision AND f.user_id = CAST(#{userId, jdbcType=VARCHAR} AS uuid)
AND f.path IN
#{path, jdbcType=VARCHAR}
